mapper.select:
SELECT COUNT(*) 
FROM member 
WHERE DATE(reg_date) = CURDATE();

SELECT m.member_id, m.member_name, m.member_email, m.role, m.status, m.reg_date, s.end_date FROM member m LEFT JOIN member_suspension s ON s.member_id = m.member_id AND (s.end_date IS NULL OR s.end_date > NOW())
AND m.role = #{role}
AND m.status = #{status}
AND (m.member_name LIKE CONCAT('%', #{keyword}, '%') OR m.member_email LIKE CONCAT('%', #{keyword}, '%') OR m.member_id LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.reg_date ASC ORDER BY m.member_name ASC ORDER BY m.reg_date DESC
LIMIT #{start}, #{count}

SELECT COUNT(*) FROM member m
AND m.role = #{role}
AND m.status = #{status}
AND (m.member_name LIKE CONCAT('%', #{keyword}, '%') OR m.member_email LIKE CONCAT('%', #{keyword}, '%') OR m.member_id LIKE CONCAT('%', #{keyword}, '%'))

select member_id, member_name, member_email, reg_date, provider, status
from member
where member_id = #{memberId}
